#include <config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "htslib/hfile.h"
#include "htslib/hts.h"
#include "htslib/sam.h"

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *copy = malloc(sz);
    if (!copy) return 1;
    if (fread(copy, 1, sz, f) != (size_t)sz) return 1;
    fclose(f);
    hFILE *memfile = hopen("mem:", "rb:", copy, sz);
    if (memfile == NULL) { free(copy); return 0; }
    htsFile *ht_file = hts_hopen(memfile, "data", "rb");
    if (ht_file == NULL) {
        fprintf(stderr, "hts_hopen failed\n");
        if (hclose(memfile) != 0) abort();
        return 0;
    }
    fprintf(stderr, "format category=%d\n", ht_file->format.category);
    if (ht_file->format.category == sequence_data) {
        samFile *out = sam_open("/dev/null", "w");
        if (!out) abort();
        sam_hdr_t *hdr = sam_hdr_read(ht_file);
        if (hdr == NULL) { fprintf(stderr, "sam_hdr_read failed\n"); return 0; }
        fprintf(stderr, "sam_hdr_read OK\n");
        (void) sam_hdr_count_lines(hdr, "SQ");
        fprintf(stderr, "count_lines done\n");
        if (sam_hdr_write(out, hdr) != 0) {
            fprintf(stderr, "sam_hdr_write failed\n");
            sam_hdr_destroy(hdr);
            return 0;
        }
        fprintf(stderr, "sam_hdr_write OK\n");
        sam_hdr_destroy(hdr);
    }
    hts_close_or_abort(ht_file);
    return 0;
}
